itle":"","description":"","achievements":[],"sort_order":0},{"year":2026,"age_category":"u15","championship":"world","member_type":"coach","name":"Гробован Олександр","role":"Старший тренер","image":"assets/images/Grobovan.webp","birth_date":null,"city":"","weight":"","title":"","description":"","achievements":[],"sort_order":1}]$seed$::jsonb) AS entry(
  year INTEGER, age_category TEXT, championship TEXT, member_type TEXT, name TEXT, role TEXT,
  image TEXT, birth_date TEXT, city TEXT, weight TEXT, title TEXT, description TEXT,
  achievements JSONB, sort_order INTEGER
)
WHERE EXISTS (SELECT 1 FROM national_team_years WHERE year = entry.year)
  AND NOT EXISTS (SELECT 1 FROM national_team_seed_history WHERE seed_key = 'legacy_2026')
  AND NOT EXISTS (
    SELECT 1 FROM national_team_entries existing
    WHERE existing.year = entry.year
      AND existing.age_category = entry.age_category
      AND existing.championship = entry.championship
  );

UPDATE national_team_entries
SET image = 'assets/images/Molnar.webp'
WHERE image = 'assets/images/Molnar.webp"';

INSERT INTO national_team_seed_history (seed_key)
VALUES ('legacy_2026')
ON CONFLICT (seed_key) DO NOTHING;
